sys.setrecursionlimit(10000)

def find_cycles(edges):
    nodes = set()
    for a, b in edges:
        nodes.add(a); nodes.add(b)
    adj = {n: [] for n in nodes}
    for a, b in edges:
        adj[a].append(b)
    WHITE, GREY, BLACK = 0, 1, 2
    color = {n: WHITE for n in nodes}
    cycles = []
    def dfs(u, stack):
        color[u] = GREY
        stack.append(u)
        for v in adj[u]:
            if color[v] == GREY:
                cycles.append(stack[stack.index(v):] + [v])
            elif color[v] == WHITE:
                dfs(v, stack)
        stack.pop()
        color[u] = BLACK
    for n in sorted(nodes):
        if color[n] == WHITE:
            dfs(n, [])
    return cycles

